import { expect, test, uniqueName } from "../../fixtures";

const TAG = "@REV-06";

type DocumentOut = { id: string; kind: string; status: string };
type ExtractionOut = { id: string; kind: string; status: string };

test.describe("review vendors", () => {
  test(
    "rejecting an extraction requires a note and returns the vendor to the member",
    { tag: TAG },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor and uploads three documents.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const suffix = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;

      const createResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("REV06 Vendor"),
          category: "services",
          contact_email: `ops+${suffix}@example.test`,
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendorId = ((await createResponse.json()) as { id: string }).id;

      const kinds = ["w9", "insurance_certificate", "contract"] as const;
      for (const kind of kinds) {
        const uploadResponse = await member.post(`/api/vendors/${vendorId}/documents`, {
          multipart: {
            kind,
            file: {
              name: `${kind}-${suffix}.pdf`,
              mimeType: "application/pdf",
              buffer: Buffer.from(`%PDF-1.4 fake ${kind} ${suffix}`),
            },
          },
        });
        expect(uploadResponse.status()).toBe(201);
      }

      // Wait for all three documents to finish extraction.
      const documentsResponse = await member.get(`/api/vendors/${vendorId}/documents`);
      expect(documentsResponse.status()).toBe(200);
      const documents = (await documentsResponse.json()) as DocumentOut[];
      expect(documents).toHaveLength(3);

      await expect
        .poll(
          async () => {
            const statuses: string[] = [];
            for (const doc of documents) {
              const r = await member.get(`/api/documents/${doc.id}`);
              statuses.push(((await r.json()) as DocumentOut).status);
            }
            return statuses.every((s) => s === "extracted");
          },
          { timeout: 60_000, intervals: [500, 1000, 2000] },
        )
        .toBe(true);

      // Submit the vendor for review.
      const submitResponse = await member.post(`/api/vendors/${vendorId}/submit`);
      expect(submitResponse.status()).toBe(200);

      // Find the W-9 extraction.
      const w9Document = documents.find((d) => d.kind === "w9");
      expect(w9Document).toBeDefined();
      const extractionResponse = await member.get(
        `/api/documents/${w9Document!.id}/extraction`,
      );
      expect(extractionResponse.status()).toBe(200);
      const extraction = (await extractionResponse.json()) as ExtractionOut;
      expect(extraction.status).toBe("pending_review");

      // Act: reject the W-9 extraction without a note.
      const noNoteResponse = await reviewer.post(
        `/api/extractions/${extraction.id}/decision`,
        { data: { decision: "reject" } },
      );

      // Assert: a note is required.
      expect(noNoteResponse.status()).toBe(422);

      // Act: reject the W-9 extraction with a note.
      const rejectResponse = await reviewer.post(
        `/api/extractions/${extraction.id}/decision`,
        { data: { decision: "reject", note: "Tax ID does not match" } },
      );
      expect(rejectResponse.status()).toBe(200);
      const rejected = (await rejectResponse.json()) as ExtractionOut;
      expect(rejected.status).toBe("rejected");

      // Assert: vendor is rejected.
      const vendorResponse = await member.get(`/api/vendors/${vendorId}`);
      expect(vendorResponse.status()).toBe(200);
      const vendor = (await vendorResponse.json()) as { status: string };
      expect(vendor.status).toBe("rejected");

      // Assert: audit event recorded.
      const auditResponse = await member.get(`/api/vendors/${vendorId}/audit`);
      expect(auditResponse.status()).toBe(200);
      const audit = (await auditResponse.json()) as {
        items: { action: string }[];
      };
      expect(audit.items.map((e) => e.action)).toContain("extraction.rejected");
    },
  );
});

export {};
